from PIL import Image
from pathlib import Path
p=Path('/app/output/lateral_test'); c='robot0_eye_in_hand'
im=np.array(Image.open(p/f'last/{c}.jpg')).astype(int)
d=np.load(p/f'depth_{c}.npy')[0].astype(float)
m=json.load(open(p/'meta.json')); cal=m['cameras'][c]; K=np.array(cal['intrinsic_cv']); T=np.array(cal['cam2world_gl']);
