 if seen[y,x]: continue
 st=[(y,x)]; seen[y,x]=1; pts=[]
 while st:
  yy,xx=st.pop(); pts.append((yy,xx))
  for y2 in range(max(0,yy-1),min(240,yy+2)):
   for x2 in range(max(0,xx-1),min(320,xx+2)):
    if mask[y2,x2] and not seen[y2,x2]: seen[y2,x2]=1;st.append((y2,x2))
 if len(pts)>4: comps.append(pts)
for pts in sorted(comps,key=len,reverse=True)[:10]:
 arr=np.array(pts); ys,xs=arr.T; print('comp',len(pts),'bbox',xs.min(),ys.min(),xs.max(),ys.max(),'rgb',im[ys,xs].mean(0),'dep',np.median(d[ys,xs]))
